-- A new grant cannot revive an earlier recipient-specific preparation or file.
ALTER TABLE s_matter_update_jobs ADD COLUMN recipient_grant_id TEXT;
UPDATE s_matter_update_jobs SET recipient_grant_id=(SELECT g.id FROM s_portal_grants g JOIN s_matter_updates u ON u.id=s_matter_update_jobs.update_id WHERE g.matter_id=s_matter_update_jobs.matter_id AND g.email=s_matter_update_jobs.recipient AND g.granted_at<=u.approved_at AND g.kind IN('client','co_client','delegate') AND g.revoked_at IS NULL ORDER BY g.granted_at DESC,g.id DESC LIMIT 1);
CREATE TRIGGER s_update_recipient_no_update BEFORE UPDATE OF recipient_grant_id ON s_matter_update_jobs BEGIN SELECT RAISE(ABORT,'Approved recipient bindings are immutable'); END;
CREATE TABLE s_invoice_delivery_grants(delivery_id TEXT PRIMARY KEY REFERENCES s_invoice_deliveries(id),grant_id TEXT NOT NULL REFERENCES s_portal_grants(id));
INSERT INTO s_invoice_delivery_grants SELECT d.id,(SELECT g.id FROM s_portal_grants g WHERE g.matter_id=b.matter_id AND g.email=d.recipient AND g.kind IN('client','co_client','payer') AND g.granted_at<=d.created_at AND g.revoked_at IS NULL ORDER BY g.granted_at DESC,g.id DESC LIMIT 1) FROM s_invoice_deliveries d JOIN s_bills b ON b.id=d.bill_id WHERE EXISTS(SELECT 1 FROM s_portal_grants g WHERE g.matter_id=b.matter_id AND g.email=d.recipient AND g.kind IN('client','co_client','payer') AND g.granted_at<=d.created_at AND g.revoked_at IS NULL);
CREATE TABLE s_payer_statement_grants(statement_id TEXT NOT NULL REFERENCES s_payer_statements(id),matter_id TEXT NOT NULL REFERENCES s_matters(id),grant_id TEXT NOT NULL REFERENCES s_portal_grants(id),PRIMARY KEY(statement_id,matter_id));
INSERT INTO s_payer_statement_grants SELECT s.id,selected.value,(SELECT g.id FROM s_portal_grants g WHERE g.matter_id=selected.value AND g.email=s.recipient AND g.kind IN('client','co_client','payer') AND g.granted_at<=s.created_at AND g.revoked_at IS NULL ORDER BY g.granted_at DESC,g.id DESC LIMIT 1) FROM s_payer_statements s,json_each(COALESCE(json_extract(s.snapshot,'$.matterIds'),json_array(s.matter_id))) selected WHERE EXISTS(SELECT 1 FROM s_portal_grants g WHERE g.matter_id=selected.value AND g.email=s.recipient AND g.kind IN('client','co_client','payer') AND g.granted_at<=s.created_at AND g.revoked_at IS NULL);
CREATE TRIGGER s_delivery_grant_no_update BEFORE UPDATE ON s_invoice_delivery_grants BEGIN SELECT RAISE(ABORT,'Delivery recipient bindings are immutable'); END;
CREATE TRIGGER s_statement_grant_no_update BEFORE UPDATE ON s_payer_statement_grants BEGIN SELECT RAISE(ABORT,'Statement recipient bindings are immutable'); END;
CREATE TABLE s_collection_recipient_grants(collection_id TEXT PRIMARY KEY REFERENCES s_collection_sequences(id),grant_id TEXT NOT NULL REFERENCES s_portal_grants(id));
INSERT INTO s_collection_recipient_grants SELECT s.id,(SELECT g.id FROM s_portal_grants g WHERE g.matter_id=s.matter_id AND g.email=s.recipient AND g.granted_at<=s.approved_at AND g.revoked_at IS NULL ORDER BY g.granted_at DESC,g.id DESC LIMIT 1) FROM s_collection_sequences s WHERE EXISTS(SELECT 1 FROM s_portal_grants g WHERE g.matter_id=s.matter_id AND g.email=s.recipient AND g.granted_at<=s.approved_at AND g.revoked_at IS NULL);
CREATE TRIGGER s_collection_grant_no_update BEFORE UPDATE ON s_collection_recipient_grants BEGIN SELECT RAISE(ABORT,'Collection recipient bindings are immutable'); END;
CREATE TABLE s_production_access_stops(share_id TEXT PRIMARY KEY REFERENCES s_production_shares(id),stopped_by TEXT NOT NULL,stopped_at TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE s_production_recipient_grants(share_id TEXT PRIMARY KEY REFERENCES s_production_shares(id),grant_id TEXT NOT NULL REFERENCES s_portal_grants(id));
CREATE TRIGGER s_production_recipient_no_update BEFORE UPDATE ON s_production_recipient_grants BEGIN SELECT RAISE(ABORT,'Production recipient bindings are immutable'); END;
CREATE TRIGGER s_production_stop_no_update BEFORE UPDATE ON s_production_access_stops BEGIN SELECT RAISE(ABORT,'Production access stops are retained'); END;
